//! Deterministic context compilation.
//!
//! Every section is generated by code, ordered by stability, and bounded by a
//! hard token budget. The compiler never asks a model to summarize state.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context as _, Result};
use loom_core::{estimate_tokens, TaskSpec, TaskStatus};
use loom_store::{sha256_hex, Project};
use serde::{Deserialize, Serialize};

use crate::prompt::{PromptRole, PromptTemplate};

pub const CONTEXT_VERSION: &str = "1.0";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ContextKind {
    Main,
    Worker,
    Judgment,
}

impl ContextKind {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Main => "main",
            Self::Worker => "worker",
            Self::Judgment => "judgment",
        }
    }

    /// Hard budgets from `doc/08` §6.2 and `doc/04` §3.1.
    pub fn budget(self) -> ContextBudget {
        match self {
            Self::Main => ContextBudget {
                total_tokens: 30_000,
                system: 6_000,
                goal: 2_000,
                constraints: 2_000,
                task: 4_000,
                dependencies: 3_000,
                snippets: 10_000,
                failure: 4_000,
                schema: 2_000,
            },
            Self::Worker => ContextBudget {
                total_tokens: 24_000,
                system: 4_000,
                goal: 1_000,
                constraints: 1_000,
                task: 4_000,
                dependencies: 1_000,
                snippets: 12_000,
                failure: 4_000,
                schema: 1_000,
            },
            Self::Judgment => ContextBudget {
                total_tokens: 8_000,
                system: 2_000,
                goal: 500,
                constraints: 500,
                task: 1_500,
                dependencies: 1_000,
                snippets: 1_500,
                failure: 1_000,
                schema: 500,
            },
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct ContextBudget {
    pub total_tokens: usize,
    pub system: usize,
    pub goal: usize,
    pub constraints: usize,
    pub task: usize,
    pub dependencies: usize,
    pub snippets: usize,
    pub failure: usize,
    pub schema: usize,
}

#[derive(Debug, Clone)]
pub struct FailedAcceptance {
    pub id: String,
    pub cmd: String,
    pub exit: i32,
    pub log_path: String,
}

#[derive(Debug, Clone, Default)]
pub struct FailurePack {
    pub attempt: u32,
    pub failures: Vec<FailedAcceptance>,
    pub log_excerpt: String,
    pub diff_ref: Option<String>,
    pub evidence_paths: Vec<String>,
}

pub struct CompileRequest<'a> {
    pub project: &'a Project,
    pub task: &'a TaskSpec,
    pub dependencies: &'a [TaskSpec],
    pub statuses: BTreeMap<String, TaskStatus>,
    pub failure_pack: Option<&'a FailurePack>,
    pub kind: ContextKind,
    pub budget: Option<ContextBudget>,
    pub prompt: &'a PromptTemplate,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct ContextSection {
    pub name: String,
    pub source: String,
    pub file: String,
    pub bytes: usize,
    pub tokens: usize,
    pub cap_tokens: usize,
    pub truncated: bool,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct InputHash {
    pub path: String,
    pub sha256: String,
    pub bytes: u64,
    pub tokens: usize,
    pub must_read: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub range: Option<[u32; 2]>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct ContextManifest {
    pub schema_version: String,
    pub task_id: String,
    pub goal_id: String,
    pub kind: String,
    pub prompt_role: String,
    pub prompt_version: String,
    pub total_budget_tokens: usize,
    pub total_tokens: usize,
    pub stable_prefix_tokens: usize,
    pub degraded: bool,
    pub sections: Vec<ContextSection>,
    pub input_hashes: Vec<InputHash>,
    pub notes: Vec<String>,
}

impl Default for ContextManifest {
    fn default() -> Self {
        Self {
            schema_version: CONTEXT_VERSION.to_string(),
            task_id: String::new(),
            goal_id: String::new(),
            kind: String::new(),
            prompt_role: String::new(),
            prompt_version: String::new(),
            total_budget_tokens: 0,
            total_tokens: 0,
            stable_prefix_tokens: 0,
            degraded: false,
            sections: Vec::new(),
            input_hashes: Vec::new(),
            notes: Vec::new(),
        }
    }
}

#[derive(Debug, Clone)]
pub struct CompiledContext {
    pub manifest: ContextManifest,
    pub sections: Vec<SectionContent>,
    pub packet: String,
}

#[derive(Debug, Clone)]
pub struct SectionContent {
    pub name: String,
    pub file: String,
    pub text: String,
}

impl CompiledContext {
    /// Write the packet and every section under `dir`, plus the manifest.
    pub fn write(&self, dir: &Path) -> Result<Vec<PathBuf>> {
        fs::create_dir_all(dir).with_context(|| format!("create {}", dir.display()))?;
        let mut written = Vec::new();

        for section in &self.sections {
            let path = dir.join(&section.file);
            fs::write(&path, &section.text).with_context(|| format!("write {}", path.display()))?;
            written.push(path);
        }

        let packet = dir.join("packet.md");
        fs::write(&packet, &self.packet).with_context(|| format!("write {}", packet.display()))?;
        written.push(packet);

        let manifest = dir.join("manifest.json");
        let text = serde_json::to_string_pretty(&self.manifest)?;
        fs::write(&manifest, format!("{text}\n"))
            .with_context(|| format!("write {}", manifest.display()))?;
        written.push(manifest);
        Ok(written)
    }
}

struct Draft {
    name: &'static str,
    source: &'static str,
    file: String,
    text: String,
    cap: usize,
    essential: bool,
    truncated: bool,
}

fn fit(text: &str, max_tokens: usize) -> (String, bool) {
    if estimate_tokens(text) <= max_tokens {
        return (text.to_string(), false);
    }
    let mut low = 0usize;
    let mut high = text.len();
    while low < high {
        let mid = low + (high - low).div_ceil(2);
        let mut boundary = mid;
        while boundary > 0 && !text.is_char_boundary(boundary) {
            boundary -= 1;
        }
        if boundary == 0 {
            break;
        }
        if estimate_tokens(&text[..boundary]) <= max_tokens {
            low = boundary;
        } else {
            high = boundary - 1;
        }
    }
    (text[..low].to_string(), true)
}

pub fn compile(request: &CompileRequest<'_>) -> Result<CompiledContext> {
    let task = request.task;
    let budget = request.budget.unwrap_or_else(|| request.kind.budget());
    let mut notes: Vec<String> = Vec::new();

    let system_text = render_system(request)?;
    let goal_text = read_human_file(request.project, "goal.md", budget.goal, &mut notes);
    let constraints_text =
        render_constraints(task, request.project, budget.constraints, &mut notes);
    let task_text = serde_json::to_string_pretty(task)?;
    if estimate_tokens(&task_text) > budget.task {
        bail!(
            "TaskSpec for {} exceeds the {} context budget ({} tokens); split the task",
            task.task_id,
            request.kind.as_str(),
            estimate_tokens(&task_text)
        );
    }
    let dependency_text = render_dependencies(task, request.dependencies, &request.statuses);
    let (snippet_text, inputs, snippet_notes) =
        render_inputs(request.project, task, budget.snippets)?;
    notes.extend(snippet_notes);
    let failure_text = request
        .failure_pack
        .as_ref()
        .map(|pack| render_failure(pack));
    let schema_text = output_contract(task, request.prompt.role);

    let mut drafts = vec![
        Draft {
            name: "system",
            source: "prompt",
            file: "system.md".to_string(),
            text: system_text,
            cap: budget.system,
            essential: true,
            truncated: false,
        },
        Draft {
            name: "goal",
            source: ".loom/goal.md",
            file: "goal.md".to_string(),
            text: goal_text,
            cap: budget.goal,
            essential: false,
            truncated: false,
        },
        Draft {
            name: "constraints",
            source: "task+human",
            file: "constraints.md".to_string(),
            text: constraints_text,
            cap: budget.constraints,
            essential: false,
            truncated: false,
        },
        Draft {
            name: "task",
            source: "TaskSpec",
            file: "task.json".to_string(),
            text: task_text,
            cap: budget.task,
            essential: true,
            truncated: false,
        },
        Draft {
            name: "dependencies",
            source: "tasks",
            file: "dependencies.md".to_string(),
            text: dependency_text,
            cap: budget.dependencies,
            essential: false,
            truncated: false,
        },
        Draft {
            name: "snippets",
            source: "inputs",
            file: "snippets.md".to_string(),
            text: snippet_text,
            cap: budget.snippets,
            essential: false,
            truncated: false,
        },
    ];
    if let Some(text) = failure_text {
        drafts.push(Draft {
            name: "failure",
            source: "verify",
            file: "failure.md".to_string(),
            text,
            cap: budget.failure,
            essential: false,
            truncated: false,
        });
    }
    drafts.push(Draft {
        name: "schema",
        source: "receipt",
        file: "schema.md".to_string(),
        text: schema_text,
        cap: budget.schema,
        essential: true,
        truncated: false,
    });

    let essential_tokens: usize = drafts
        .iter()
        .filter(|draft| draft.essential)
        .map(|draft| draft.cap)
        .sum();
    if essential_tokens > budget.total_tokens {
        bail!(
            "essential context sections need {essential_tokens} tokens > budget {}",
            budget.total_tokens
        );
    }

    for draft in &mut drafts {
        let (text, truncated) = fit(&draft.text, draft.cap);
        draft.text = text;
        draft.truncated = truncated;
        if truncated {
            notes.push(format!("section {} was truncated", draft.name));
        }
    }

    let trim_order = ["snippets", "failure", "dependencies", "constraints", "goal"];
    loop {
        let total: usize = drafts
            .iter()
            .map(|draft| estimate_tokens(&draft.text))
            .sum();
        if total <= budget.total_tokens {
            break;
        }
        let excess = total - budget.total_tokens;
        let mut shrunk = false;
        for name in trim_order {
            let Some(draft) = drafts
                .iter_mut()
                .find(|draft| draft.name == name && estimate_tokens(&draft.text) > 0)
            else {
                continue;
            };
            let new_cap = estimate_tokens(&draft.text).saturating_sub(excess);
            let (text, _) = fit(&draft.text, new_cap);
            let before = estimate_tokens(&draft.text);
            draft.text = text;
            if estimate_tokens(&draft.text) < before {
                notes.push(format!(
                    "section {} reduced to fit the hard budget",
                    draft.name
                ));
                shrunk = true;
                break;
            }
        }
        if !shrunk {
            let total: usize = drafts
                .iter()
                .map(|draft| estimate_tokens(&draft.text))
                .sum();
            bail!(
                "context does not fit the {}-token budget (needs {total} tokens); remove inputs or split the task",
                budget.total_tokens
            );
        }
    }

    let mut sections = Vec::new();
    let mut contents = Vec::new();
    let mut packet = String::new();
    let mut stable_prefix_tokens = 0usize;

    for draft in &drafts {
        let tokens = estimate_tokens(&draft.text);
        if matches!(draft.name, "system" | "goal" | "constraints") {
            stable_prefix_tokens += tokens;
        }
        sections.push(ContextSection {
            name: draft.name.to_string(),
            source: draft.source.to_string(),
            file: draft.file.clone(),
            bytes: draft.text.len(),
            tokens,
            cap_tokens: draft.cap,
            truncated: draft.truncated,
        });
        packet.push_str(&format!("<!-- loom:section {} -->\n", draft.name));
        packet.push_str(&draft.text);
        if !draft.text.ends_with('\n') {
            packet.push('\n');
        }
        packet.push('\n');
        contents.push(SectionContent {
            name: draft.name.to_string(),
            file: draft.file.clone(),
            text: draft.text.clone(),
        });
    }

    let total_tokens = estimate_tokens(&packet);
    if total_tokens > budget.total_tokens {
        bail!(
            "compiled packet is {total_tokens} tokens > budget {}",
            budget.total_tokens
        );
    }

    let manifest = ContextManifest {
        schema_version: CONTEXT_VERSION.to_string(),
        task_id: task.task_id.clone(),
        goal_id: task.goal_id.clone(),
        kind: request.kind.as_str().to_string(),
        prompt_role: request.prompt.role.as_str().to_string(),
        prompt_version: request.prompt.version.to_string(),
        total_budget_tokens: budget.total_tokens,
        total_tokens,
        stable_prefix_tokens,
        degraded: sections.iter().any(|section| section.truncated),
        sections,
        input_hashes: inputs,
        notes,
    };

    Ok(CompiledContext {
        manifest,
        sections: contents,
        packet,
    })
}

fn render_system(request: &CompileRequest<'_>) -> Result<String> {
    let task = request.task;
    let mut vars = BTreeMap::new();
    vars.insert("task_id", task.task_id.clone());
    vars.insert("goal_id", task.goal_id.clone());
    vars.insert("role", task.role().as_str().to_string());
    vars.insert("tier", task.tier.as_str().to_string());
    vars.insert("report_path", task.output.report_path.clone());

    let mut text = request.prompt.render(&vars)?;
    text.push_str("\n\n");
    text.push_str(TOOL_CONTRACT);
    Ok(text)
}

const TOOL_CONTRACT: &str = "## 工具与交付契约\n\
- 检索只用路径/符号/行号；禁止整仓 dump 与原始 JSON/HTML 回贴。\n\
- 超过阈值的结果写 artifact，只回路径 + 摘要 + 行号。\n\
- 代码改动用 diff 表达；只有新文件才允许全文。\n\
- 跨边界只传路径、sha256、行号、diff 路径、verify 日志路径。\n\
";

fn read_human_file(project: &Project, name: &str, cap: usize, notes: &mut Vec<String>) -> String {
    let path = project.loom_dir().join(name);
    let Ok(text) = fs::read_to_string(&path) else {
        notes.push(format!(".loom/{name} is missing"));
        return String::new();
    };
    let (text, _) = fit(&text, cap);
    text
}

fn render_constraints(
    task: &TaskSpec,
    project: &Project,
    cap: usize,
    notes: &mut Vec<String>,
) -> String {
    let mut text = String::from("# constraints (task)\n");
    text.push_str(&format!(
        "- max_files_touched: {}\n",
        task.constraints
            .max_files_touched
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unlimited".to_string())
    ));
    text.push_str(&format!(
        "- no_new_dependencies: {}\n",
        task.constraints.no_new_dependencies
    ));
    for style in &task.constraints.style {
        text.push_str(&format!("- style: {style}\n"));
    }
    if let Some(notes_text) = &task.constraints.notes {
        text.push_str(&format!("- notes: {notes_text}\n"));
    }
    text.push_str("\n# constraints (human)\n");
    text.push_str(&read_human_file(
        project,
        "constraints.md",
        cap.saturating_sub(estimate_tokens(&text)),
        notes,
    ));
    let (text, _) = fit(&text, cap);
    text
}

fn render_dependencies(
    task: &TaskSpec,
    dependencies: &[TaskSpec],
    statuses: &BTreeMap<String, TaskStatus>,
) -> String {
    if dependencies.is_empty() && task.depends_on.is_empty() {
        return "# dependencies\n(none)\n".to_string();
    }
    let mut text = String::from("# dependencies\n");
    for dep_id in &task.depends_on {
        let status = statuses
            .get(dep_id)
            .copied()
            .unwrap_or(TaskStatus::Pending)
            .as_str();
        if let Some(dep) = dependencies.iter().find(|dep| &dep.task_id == dep_id) {
            text.push_str(&format!(
                "- {dep_id} [{status}] {} ({} accepts)\n",
                dep.title,
                dep.acceptance.len()
            ));
        } else {
            text.push_str(&format!("- {dep_id} [{status}]\n"));
        }
    }
    text
}

fn render_inputs(
    project: &Project,
    task: &TaskSpec,
    cap: usize,
) -> Result<(String, Vec<InputHash>, Vec<String>)> {
    let policy = task.context_policy.clone().unwrap_or_default();
    let must_count = task.inputs.iter().filter(|input| input.must_read).count();
    if must_count > policy.max_must_read_files {
        bail!(
            "{} has {must_count} must_read inputs > max {}",
            task.task_id,
            policy.max_must_read_files
        );
    }

    let mut text = String::from("# inputs\n");
    let mut hashes = Vec::new();
    let mut notes = Vec::new();
    let mut remaining = cap;

    for input in &task.inputs {
        let resolved = match project.resolve_path(&input.path) {
            Ok(path) => path,
            Err(error) if input.must_read => {
                bail!("must_read input {} is unreadable: {error}", input.path)
            }
            Err(_) => {
                notes.push(format!("input {} is missing; skipped", input.path));
                continue;
            }
        };
        let bytes = match fs::read(&resolved) {
            Ok(bytes) => bytes,
            Err(error) if input.must_read => {
                bail!("must_read input {} is unreadable: {error}", input.path)
            }
            Err(_) => {
                notes.push(format!("input {} is missing; skipped", input.path));
                continue;
            }
        };
        let content = match String::from_utf8(bytes.clone()) {
            Ok(content) => content,
            Err(_) if input.must_read => bail!("must_read input {} is not UTF-8", input.path),
            Err(_) => {
                notes.push(format!("input {} is not UTF-8; skipped", input.path));
                continue;
            }
        };
        let hash = sha256_hex(&bytes);
        if let Some(expected) = &input.sha256 {
            if expected != &hash {
                bail!(
                    "input {} sha256 mismatch: expected {expected}, got {hash}",
                    input.path
                );
            }
        }

        let lines: Vec<&str> = content.lines().collect();
        let snippet = match input.range {
            Some([start, end]) => {
                let start = start as usize;
                if start == 0 || start > lines.len() {
                    bail!(
                        "input {} range starts outside the file ({} lines)",
                        input.path,
                        lines.len()
                    );
                }
                lines
                    .iter()
                    .skip(start - 1)
                    .take((end as usize).saturating_sub(start) + 1)
                    .copied()
                    .collect::<Vec<_>>()
                    .join("\n")
            }
            None => content.clone(),
        };

        let header = match input.range {
            Some([start, end]) => format!("\n### {} (L{start}-L{end}) sha256={hash}\n", input.path),
            None => format!("\n### {} sha256={hash}\n", input.path),
        };
        let needed = estimate_tokens(&header) + estimate_tokens(&snippet);

        if input.must_read {
            if needed > remaining {
                bail!(
                    "must_read input {} needs {needed} tokens, only {remaining} left",
                    input.path
                );
            }
        } else if needed > remaining {
            let (snippet, _) = fit(&snippet, remaining.saturating_sub(16));
            notes.push(format!("input {} was truncated", input.path));
            text.push_str(&header);
            text.push_str(&snippet);
            text.push('\n');
            hashes.push(InputHash {
                path: input.path.clone(),
                sha256: hash,
                bytes: bytes.len() as u64,
                tokens: estimate_tokens(&snippet),
                must_read: input.must_read,
                range: input.range,
            });
            break;
        }

        text.push_str(&header);
        text.push_str(&snippet);
        text.push('\n');
        remaining = remaining.saturating_sub(needed);
        hashes.push(InputHash {
            path: input.path.clone(),
            sha256: hash,
            bytes: bytes.len() as u64,
            tokens: estimate_tokens(&snippet),
            must_read: input.must_read,
            range: input.range,
        });
    }

    if must_count > 0 {
        let must_tokens: usize = hashes
            .iter()
            .filter(|hash| hash.must_read)
            .map(|hash| hash.tokens)
            .sum();
        if must_tokens > policy.max_must_read_tokens {
            bail!(
                "must_read inputs need {must_tokens} tokens > policy {}",
                policy.max_must_read_tokens
            );
        }
    }

    Ok((text, hashes, notes))
}

fn render_failure(pack: &FailurePack) -> String {
    let mut text = format!("# failure pack (attempt {})\n", pack.attempt.max(1));
    if pack.failures.is_empty() {
        text.push_str("(no failed acceptance recorded)\n");
    } else {
        text.push_str("## failed acceptance\n");
        for failure in &pack.failures {
            text.push_str(&format!(
                "- {} exit={} cmd={} log={}\n",
                failure.id, failure.exit, failure.cmd, failure.log_path
            ));
        }
    }
    if let Some(diff_ref) = &pack.diff_ref {
        text.push_str(&format!("\n## diff\n{diff_ref}\n"));
    }
    if !pack.log_excerpt.is_empty() {
        text.push_str("\n## log excerpt\n");
        text.push_str(pack.log_excerpt.trim_end());
        text.push('\n');
    }
    if !pack.evidence_paths.is_empty() {
        text.push_str("\n## evidence\n");
        for path in &pack.evidence_paths {
            text.push_str(&format!("- {path}\n"));
        }
    }
    text
}

fn output_contract(task: &TaskSpec, role: PromptRole) -> String {
    match role {
        PromptRole::Worker => format!(
            "## 输出契约\n\
             结束时只输出四行回执（顺序固定，无前言后记/代码块/空行）：\n\
             status: done|blocked|needs_input|failed|budget_exceeded\n\
             branch: {}@<sha>\n\
             verify: {}=pass/fail/skip; log=<path>\n\
             report: {}\n\
             \n\
             必需产物：{}\n\
             \n\
             verify 只由 orchestrator 重跑决定；worker 的 status=done 不是验收。\n",
            task.workspace.branch,
            task.acceptance
                .iter()
                .map(|item| item.id.as_str())
                .collect::<Vec<_>>()
                .join(","),
            task.output.report_path,
            if task.output.required_artifacts.is_empty() {
                "none".to_string()
            } else {
                task.output.required_artifacts.join(", ")
            }
        ),
        PromptRole::Orchestrator => "## 输出契约\n\
             只允许：A TaskSpec(JSON)；B 状态更新(任务 ID + 状态 + 证据路径)；\
             C 升级请求(证据包路径 + 待决问题，≤200 字)；D run 总结(≤300 字 + 指标)。\n"
            .to_string(),
        PromptRole::Judgment => "## 输出契约\n\
             只输出 JSON：{\"decision\":\"fix_plan|split|reject|human\",\"plan\":[...],\
             \"refs\":[...],\"max_attempts\":1,\"human_required\":false,\
             \"evidence_gaps\":[...]}\n"
            .to_string(),
        PromptRole::Review => "## 输出契约\n\
             输出 verdict(pass|request_changes|human)、reasons(≤5，引用路径/行号)、\
             required_changes(≤5，可执行)。\n"
            .to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::prompt;
    use loom_core::{
        Acceptance, TaskConstraints, TaskInput, TaskOutput, TaskRole, TaskWorkspace, Tier,
        WorkspaceMode, TASK_VERSION,
    };
    use std::collections::BTreeMap;

    fn project() -> Project {
        let dir = tempfile::tempdir().expect("tempdir");
        let project = Project::at(dir.path());
        fs::create_dir_all(project.loom_dir()).expect("mkdir");
        fs::write(
            project.loom_dir().join("goal.md"),
            "# GOAL\n\n实现登录并回归测试。\n",
        )
        .expect("write goal");
        fs::write(
            project.loom_dir().join("constraints.md"),
            "# Constraints\n\n不新增依赖。\n",
        )
        .expect("write constraints");
        std::mem::forget(dir);
        project
    }

    fn task() -> TaskSpec {
        TaskSpec {
            schema_version: TASK_VERSION.into(),
            task_id: "T-20261104-001".into(),
            goal_id: "G-20261104-auth".into(),
            title: "实现登录".into(),
            role: TaskRole::Implement,
            tier: Tier::Worker,
            workspace: TaskWorkspace {
                mode: WorkspaceMode::InPlace,
                base_ref: "main".into(),
                branch: "agent/T-20261104-001".into(),
                allowed_paths: vec!["src/**".into()],
                forbidden_paths: vec![],
            },
            inputs: vec![TaskInput {
                path: "src/lib.rs".into(),
                sha256: None,
                range: Some([1, 3]),
                must_read: true,
            }],
            constraints: TaskConstraints {
                max_files_touched: Some(8),
                no_new_dependencies: true,
                style: vec!["follow existing envelope".into()],
                notes: None,
            },
            acceptance: vec![Acceptance {
                id: "A1".into(),
                cmd: "true".into(),
                expect_exit: 0,
                timeout_s: 30,
            }],
            budget: loom_core::TaskBudget::default(),
            output: TaskOutput {
                receipt: "4-line".into(),
                report_path: ".loom/runs/R-1/outbox/report.md".into(),
                required_artifacts: vec!["git_diff".into()],
            },
            ..TaskSpec::default()
        }
    }

    fn request<'a>(project: &'a Project, task: &'a TaskSpec) -> CompileRequest<'a> {
        CompileRequest {
            project,
            task,
            dependencies: &[],
            statuses: BTreeMap::from([("T-20261104-001".to_string(), TaskStatus::Pending)]),
            failure_pack: None,
            kind: ContextKind::Worker,
            budget: None,
            prompt: prompt::get(PromptRole::Worker).expect("prompt"),
        }
    }

    #[test]
    fn compiles_within_budget_and_is_deterministic() {
        let dir = tempfile::tempdir().expect("tempdir");
        let project = Project::at(dir.path());
        fs::create_dir_all(project.loom_dir()).expect("mkdir");
        fs::write(
            project.loom_dir().join("goal.md"),
            "# GOAL\n\n实现登录并回归测试。\n",
        )
        .expect("write goal");
        fs::write(
            project.loom_dir().join("constraints.md"),
            "# Constraints\n\n不新增依赖。\n",
        )
        .expect("write constraints");
        let source = project.root.join("src");
        fs::create_dir_all(&source).expect("mkdir src");
        fs::write(source.join("lib.rs"), "fn a() {}\nfn b() {}\nfn c() {}\n")
            .expect("write source");

        let spec = task();
        let request = request(&project, &spec);
        let first = compile(&request).expect("compile");
        let second = compile(&request).expect("compile");

        assert!(first.manifest.total_tokens <= ContextKind::Worker.budget().total_tokens);
        assert!(first.manifest.stable_prefix_tokens > 0);
        assert!(!first.manifest.degraded);
        assert_eq!(first.packet, second.packet);
        assert!(first.packet.contains("<!-- loom:section system -->"));
        assert!(first.packet.contains("<!-- loom:section schema -->"));
        assert!(first.manifest.input_hashes[0].sha256.len() == 64);
    }

    #[test]
    fn missing_must_read_input_fails() {
        let project = project();
        let spec = task();
        let request = request(&project, &spec);
        let error = compile(&request).expect_err("must fail");
        assert!(format!("{error:#}").contains("must_read input"));
    }

    #[test]
    fn hash_mismatch_fails() {
        let dir = tempfile::tempdir().expect("tempdir");
        let project = Project::at(dir.path());
        let source = project.root.join("src");
        fs::create_dir_all(&source).expect("mkdir");
        fs::write(source.join("lib.rs"), "fn a() {}\n").expect("write");
        let mut spec = task();
        spec.inputs[0].sha256 = Some("0".repeat(64));
        let request = request(&project, &spec);
        let error = compile(&request).expect_err("must fail");
        assert!(format!("{error:#}").contains("sha256 mismatch"));
    }

    #[test]
    fn writes_packet_and_manifest() {
        let dir = tempfile::tempdir().expect("tempdir");
        let project = Project::at(dir.path());
        let source = project.root.join("src");
        fs::create_dir_all(&source).expect("mkdir");
        fs::write(source.join("lib.rs"), "fn a() {}\n").expect("write");

        let spec = task();
        let compiled = compile(&request(&project, &spec)).expect("compile");
        let out = dir.path().join("packet");
        let written = compiled.write(&out).expect("write");
        assert!(written.iter().any(|path| path.ends_with("packet.md")));
        assert!(out.join("manifest.json").exists());
        assert!(out.join("task.json").exists());
    }

    #[test]
    fn failure_pack_is_included_when_present() {
        let dir = tempfile::tempdir().expect("tempdir");
        let project = Project::at(dir.path());
        let source = project.root.join("src");
        fs::create_dir_all(&source).expect("mkdir");
        fs::write(source.join("lib.rs"), "fn a() {}\n").expect("write");

        let spec = task();
        let mut request = request(&project, &spec);
        let failure = FailurePack {
            attempt: 2,
            failures: vec![FailedAcceptance {
                id: "A1".into(),
                cmd: "cargo test".into(),
                exit: 101,
                log_path: ".loom/logs/verify.log".into(),
            }],
            log_excerpt: "error: assertion failed".into(),
            diff_ref: None,
            evidence_paths: vec![".loom/logs/verify.log".into()],
        };
        request.failure_pack = Some(&failure);
        let compiled = compile(&request).expect("compile");
        assert!(compiled.packet.contains("failure pack"));
        assert!(compiled.packet.contains("assertion failed"));
    }

    #[test]
    fn budget_trims_snippets_before_essential_sections() {
        let dir = tempfile::tempdir().expect("tempdir");
        let project = Project::at(dir.path());
        let source = project.root.join("src");
        fs::create_dir_all(&source).expect("mkdir");
        let big = "fn a() {}\n".repeat(5_000);
        fs::write(source.join("lib.rs"), &big).expect("write");

        let mut spec = task();
        spec.inputs[0].range = None;
        spec.inputs[0].must_read = false;
        spec.inputs.push(TaskInput {
            path: "src/lib.rs".into(),
            sha256: None,
            range: None,
            must_read: false,
        });
        let mut request = request(&project, &spec);
        request.kind = ContextKind::Judgment;
        request.prompt = prompt::get(PromptRole::Judgment).expect("prompt");
        let compiled = compile(&request).expect("compile");
        assert!(compiled.manifest.total_tokens <= ContextKind::Judgment.budget().total_tokens);
        assert!(compiled
            .manifest
            .sections
            .iter()
            .any(|section| section.name == "snippets" && section.truncated));
    }
}
